{
  "semantic_profile": "deterministic_finite_v1",
  "name": "orders-tenant-isolation",
  "description": "Secure specification of tenant/object access isolation: an access succeeds only when the subject is granted the tenant.",
  "enums": [],
  "entity_sets": [
    {
      "name": "subjects",
      "members": [
        "alpha",
        "bravo"
      ],
      "label": "主体",
      "description": null
    },
    {
      "name": "tenants",
      "members": [
        "acme",
        "globex"
      ],
      "label": "租户",
      "description": null
    }
  ],
  "constants": [
    {
      "name": "grant",
      "type": {
        "kind": "bool"
      },
      "index": [
        "subjects",
        "tenants"
      ],
      "value": {
        "default": false,
        "cells": [
          {
            "index": [
              "alpha",
              "acme"
            ],
            "value": true
          },
          {
            "index": [
              "alpha",
              "globex"
            ],
            "value": false
          },
          {
            "index": [
