          },
          {
            "index": [
              "bravo",
              "globex"
            ],
            "value": true
          }
        ]
      },
      "description": "the fixed grant table: which subject may use which tenant"
    }
  ],
  "state": [
    {
      "name": "accessed",
      "type": {
        "kind": "bool"
      },
      "index": [
        "subjects",
        "tenants"
      ],
      "initial": {
        "default": false,
        "cells": []
      },
      "label": "已成功访问",
      "description": "set when an access by the subject to the tenant succeeds",
      "observable": true
    }
  ],
  "actions": [
    {
      "name": "access",
      "params": [
        {
          "name": "s",
          "type": {
            "kind": "entity",
            "set": "subjects"
          }
        },
        {
          "name": "t",
          "type": {
            "kind": "entity",
            "set": "tenants"
          }
        }
      ],
      "precondition": {
        "op": "var",
        "name": "grant",
        "index": [
          {
            "op": "ref",
            "name": "s"
          },
          {
            "op": "ref",
            "name": "t"
          }
        ]
      },
      "effects": [
        {
          "kind": "assign",
          "target": {
            "var": "accessed",
            "index": [
              {
                "op": "ref",
                "name": "s"
              },
              {
                "op": "ref",
                "name": "t"
              }
            ]
          },
          "value": {
            "op": "const",
            "value": true,
            "domain": null
          }
        }
      ],
      "cost": 1,
      "label": "访问租户",
      "description": null,
      "timeout_seconds": 30.0,
      "retry": "RECONCILE_THEN_RETRY"
    }
  ],
  "properties": [
    {
      "id": "tenant_isolation",
      "kind": "invariant",
      "expr": {
        "op": "forall",
        "var": "s",
        "domain": "subjects",
        "where": null,
        "body": {
          "op": "forall",
          "var": "t",
          "domain": "tenants",
          "where": null,
          "body": {
            "op": "implies",
            "args": [
              {
                "op": "var",
                "name": "accessed",
                "index": [
                  {
                    "op": "ref",
                    "name": "s"
                  },
                  {
                    "op": "ref",
                    "name": "t"
                  }
                ]
              },
              {
                "op": "var",
                "name": "grant",
                "index": [
                  {
                    "op": "ref",
                    "name": "s"
                  },
                  {
                    "op": "ref",
                    "name": "t"
                  }
                ]
              }
            ]
          },
          "default": null
        },
        "default": null
      },
      "label": "租户隔离",
      "description": null
    }
